pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining after placement
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that are hard to fill)
    // We penalize residuals in the range [1, 9] heavily, as they are unlikely to fit future items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 15.0;
    }

    // Dynamic Lookahead Coupling:
    // If we have a next item, we want to maximize the chance that the current placement
    // leaves enough room for the next item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            // High penalty if we block the next item from fitting in this bin
            score += 50.0 * (1.0 - progress.powi(2));
        } else {
            // Reward if we leave just enough room for the next item (synergy)
            let slack = post - next_item_size as f64;
            score -= (1.0 / (slack + 1.0)) * 20.0;
        }
    }

    // Adaptive New-Bin Thresholding:
    // As the stream progresses, become increasingly conservative about opening new bins.
    // If bin_residual == bin_capacity, we are evaluating the "New Bin" option.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let new_bin_cost = 45.0 + (progress * 30.0);

        // If few bins fit the item, opening a new bin is less attractive
        if fitting_bins_count > 0 {
            score = new_bin_cost + (fitting_bins_count as f64 * 5.0);
        } else {
            score = new_bin_cost;
        }
    } else {
        // For existing bins, favor those that move the bin toward a perfectly full state (0 residual)
        // weighted by how many other bins are open (avoiding fragmentation).
        score += (open_bins_count as f64 * 2.0);

        // Interaction with mean_residual: favor bins that are closer to the mean to keep bin states uniform
        score += (post - mean_residual).abs() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" residuals 
    // that cannot accommodate typical future items.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for creating "slivers" (unusable space < 10, as items are >= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If a future item exists, prioritize bins that can fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (synergy)
            score -= 25.0 * (1.0 - progress);
        } else {
            // Penalize if this placement prevents the next item from fitting here
            score += 15.0;
        }
    }

    // 3. Global state balancing: Avoid overcrowding bins early on, prefer uniform distribution.
    // If the post_residual is significantly lower than the global mean, we are packing too tight.
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 10.0 * (1.0 - progress);
    }

    // 4. New bin management:
    // Only open a new bin if the current fit is extremely poor or we are forced.
    if bin_residual == bin_capacity {
        // Only open new if we have many bins or the current best fit is very tight (bad).
        if open_bins_count > 0 {
            score += 40.0; 
        }
    }

    // 5. Last-chance logic: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is likely wasted.
    // We penalize this heavily because items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item can fit into the new post_residual,
    // reward this bin choice to consolidate items.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: If this is an existing bin, penalize it if we have too many
    // open bins, forcing the algorithm to pack tightly into fewer bins.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    } else {
        // Penalty for opening a new bin: Only open if the existing bins are extremely poor fits.
        // We add a threshold cost to prevent unnecessary bin creation.
        score += 35.0;

        // If there is only one bin that can fit the item, opening a new one is usually bad.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Mean Residual Balancing: If the bin is much emptier than the average,
    // favor placing the item here to bring it closer to the mean.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res.powf(1.2);

    // Penalty for creating "fragmented" space (small, unusable residuals)
    // We penalize residuals that are too small to fit a median-sized item (e.g., < 20)
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_res) * 5.0;
    }

    // Lookahead logic: if next item is large, avoid leaving small residuals
    if next_item_size > 50 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Dynamic pressure: as we approach the end of the stream, favor closing bins (lower residuals)
    // more aggressively to minimize the number of open bins.
    score += progress * (open_bins_count as f64) * 2.0;

    // Discourage opening new bins unless the fit is extremely poor (high post_residual)
    if bin_residual == bin_capacity {
        // This is a new bin. Assign a baseline cost that scales with the number of open bins.
        // We only pick this if existing bins yield worse scores.
        score = 45.0 + (progress * 15.0) + (open_bins_count as f64 * 0.5);
    } else {
        // If it's a fitting bin, apply a discount based on how many other bins could fit this.
        // This spreads the load slightly to keep bins balanced.
        score -= (fitting_bins_count as f64).ln() * 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation)
    // We favor "Perfect Fit" (post_residual == 0) or "Safe Fit" (post_residual >= next_item_size)
    if post_residual == 0 {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if post_residual > 0 && post_residual < 15 {
        // Penalty for creating 'orphaned' small spaces that are unlikely to fit future items
        score += 40.0;
    }

    // 2. Bin Consolidation: If this is the last fitting bin, prioritize it to avoid creating new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the current mean residual is high
    // or the current bin_residual is extremely poor for the incoming item.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 25.0 {
            score += 10.0;
        } else {
            score += 60.0; // Strong penalty for opening new bins prematurely
        }
    }

    // 4. Modulo/Harmonic Coupling: Favor placements that leave space divisible by common item sizes
    // This reduces the entropy of the remaining residual space.
    let harmonic_fit = (post_residual % 20) as f64;
    score += harmonic_fit;

    // 5. Lookahead integration: Penalize if current placement blocks the next item from fitting
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score is the post-placement residual (Best Fit strategy).
    // We want to minimize this, but we penalize very small residuals (dead space)
    // that are unlikely to fit future items.
    let mut score = post;

    // Penalty for "near-full" bins that create unusable gaps (e.g., residual < 10).
    // This encourages filling bins completely or leaving enough room for typical items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: if the next item is large, prefer bins that have enough space
    // to accommodate it, effectively discouraging bins that will become "useless"
    // immediately after this placement.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post > 0.0 && post < next {
            score += (next - post) * 2.5;
        }
    }

    // Dynamic weighting: As the stream progresses, prioritize tighter packing
    // to avoid leaving too many bins partially filled near the end.
    // We scale the penalty for having many open bins as we approach the end.
    let open_bin_penalty = (open_bins_count as f64) * progress * 10.0;
    score += open_bin_penalty;

    // Favor bins that align with the global mean residual to keep bin states uniform,
    // reducing the variance of remaining space across the set of open bins.
    let deviation_from_mean = (post - mean_residual).abs();
    score += deviation_from_mean * 0.5;

    // New bin candidate logic:
    // If this is a new bin (bin_residual == capacity), we only want to pick it
    // if the existing bins provide a very poor fit (high post_residual or
    // high open_bins_count).
    if bin_residual == bin_capacity {
        // High cost to open a new bin, reduced slightly if many bins are already open
        // or if fitting_bins_count is low (meaning current options are limited).
        score = 80.0 + (open_bins_count as f64 * 0.5) - (fitting_bins_count as f64 * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish small residuals (Best Fit) but modulate by stream progress
    // We want tight fits early on, but prioritize bin consolidation as the stream ends
    let mut score = post.powf(1.5) * (1.0 + 0.5 * progress);

    // Penalty for creating "orphaned" space: if the remaining room is too small for any 
    // likely item (based on mean_residual), increase the score to discourage this bin.
    if post < mean_residual * 0.5 {
        score += 20.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item could fit into the current residual, 
    // we want to preserve that space. If the current item leaves a gap that 
    // perfectly matches the next item, we reward it.
    if next_item_size > 0 {
        let diff = (post as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;
    }

    // New Bin Logic: Discourage opening a new bin unless the fitting quality of 
    // existing bins is extremely poor.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the current progress is early and 
        // there are very few fitting bins, or if existing bins are too full.
        score = 45.0 + (progress * 10.0) + (open_bins_count as f64 * 0.5);
    } else {
        // If it's a tight fit, make it highly attractive (lower score)
        if post < 5.0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Strict dead space avoidance (penalizing post_residual in unusable small gaps)
    // coupled with open_bins_count pressure.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it's likely unusable.
    // We penalize these gaps heavily to encourage tighter packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Open Bins Pressure: Penalize using an existing bin if it leads to many open bins.
    // If this is an existing bin, add pressure based on current open count.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    } else {
        // If it's a new bin, penalize it less if we have many open bins already (to force reuse).
        score += 15.0 - (open_bins_count as f64 * 0.5).min(10.0);
    }

    // 3. Lookahead synergy: If the next item could fit perfectly in the remaining space, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 40.0;
        } else if gap_after_next < 10 {
            score += 20.0; // Avoid creating a new tiny gap
        }
    }

    // 4. Mean Residual balancing: Favor bins that keep the mean residual closer to the item_size,
    // preventing extreme fragmentation across the bin set.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.2;

    // 5. Last Chance logic: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
